insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('schembrunn', 'Schembrunn', '', '', '', '', 'Schönbrunn', '[{"kategorie": "wörtlich, kurz für", "text": "\"Schloss Schönbrunn\" (eines der bedeutendsten kulturellen und historischen Wahrzeichen Wiens, das zum UNESCO-Weltkulturerbe gehört)"}, {"kategorie": "", "text": "Es liegt im 13. Wiener Gemeindebezirk ([[Hietzing]]) und war über Jahrhunderte hinweg die Sommerresidenz der Habsburger Kaiserfamilie. Das Schloss und seine weitläufigen Gärten sind heute eine der meistbesuchten Touristenattraktionen in Österreich"}, {"kategorie": "hist.", "text": "Das Schloss Schönbrunn hat seinen Ursprung im 17. Jahrhundert, als [[Kaiser]] Leopold I. das Jagdschloss auf dem Gelände des heutigen Schönbrunn erbauen ließ. Der Name \"Schönbrunn\" leitet sich von einem Brunnen ab, der bei einer Jagd von Kaiser Matthias entdeckt wurde"}, {"kategorie": "", "text": "Im 18. Jahrhundert wurde das Schloss unter Kaiserin Maria Theresia erheblich erweitert und in den heutigen prachtvollen Barockstil umgebaut. Maria Theresia nutzte Schönbrunn als Hauptresidenz und ließ es zu einem der schönsten Paläste Europas ausbauen"}, {"kategorie": "Architektur", "text": "Schloss Schönbrunn ist ein beeindruckendes Beispiel barocker Architektur. Der Bau wurde von den Architekten Johann Bernhard Fischer von Erlach und Nicolaus Pacassi gestaltet"}, {"kategorie": "", "text": "Das Schloss hat eine monumentale Fassade mit insgesamt 1.441 Räumen, von denen viele prunkvoll ausgestattet sind. Zu den bekanntesten Räumen zählen die [[Große]] Galerie, der [[Spiegelsaal]] und das [[Millionenzimmer]], das mit kostbaren orientalischen Miniaturen verziert ist"}, {"kategorie": "", "text": "Der Schlosspark Schönbrunn erstreckt sich über 160 Hektar und ist ein herausragendes Beispiel für barocke Gartenkunst. Er umfasst zahlreiche Skulpturen, Brunnen und kunstvoll angelegte Alleen. Zu den besonderen Sehenswürdigkeiten im Park gehören die [[Gloriette]], ein klassizistischer Pavillon auf einem Hügel mit Blick auf das Schloss, der [[Neptunbrunnen]] und der historische Schlossgarten. Im Park befindet sich auch der [[Tiergarten]] Schönbrunn, der älteste Zoo der Welt, der 1752 gegründet wurde und heute eine Vielzahl von Tierarten beherbergt."}]'::jsonb, ''),
  ('schbiiglsoi', 'Schbiiglsoi', '', '', '', '', 'Spiegelsaal', '[{"kategorie": "allg.", "text": "prunkvoller Raum im [[Schloss]] Schönbrunn, der für seine reiche Ausstattung mit Spiegeln und seine Bedeutung im höfischen Leben der Habsburger bekannt ist"}, {"kategorie": "", "text": "Der Spiegelsaal befindet sich im Erdgeschoss des Schlosses Schönbrunn, in unmittelbarer Nähe zur [[Großen]] Galerie und anderen prächtigen Räumen des Schlosses"}, {"kategorie": "", "text": "Der Raum zeichnet sich durch seine elegante, barocke Architektur aus. Die Wände des Spiegelsaals sind vollständig mit hohen Spiegeln bedeckt, die von vergoldeten Stuckarbeiten und Ornamenten umrahmt werden. Diese Spiegel verstärken den Eindruck von Größe und Licht im Raum und erzeugen eine besondere Atmosphäre"}, {"kategorie": "", "text": "Die Decke des Spiegelsaals ist reich mit Stuck und Gemälden verziert, die Szenen aus der griechischen Mythologie und allegorische Darstellungen zeigen. Die goldenen Stuckrahmen und die kunstvollen Verzierungen sind charakteristisch für die barocke Innenausstattung des Schlosses"}, {"kategorie": "", "text": "Der Spiegelsaal ist außerdem mit wertvollen Kronleuchtern ausgestattet, die den Raum in festliches Licht tauchen und die Spiegelungen verstärken. Der Raum enthält zudem prunkvolle Möbel, die dem höfischen Leben der Zeit entsprechen"}, {"kategorie": "", "text": "Der Spiegelsaal wurde von den Habsburgern für verschiedene repräsentative Zwecke genutzt. Er diente als Ort für Konzerte, kleinere Empfänge, und als Salon für das höfische Leben"}, {"kategorie": "", "text": "Eine besonders bedeutende historische Begebenheit im Spiegelsaal war das Konzert des sechsjährigen Wolfgang Amadeus Mozart im Jahr 1762, bei dem er vor Kaiserin Maria Theresia und dem kaiserlichen Hof spielte. Dieses Ereignis trug wesentlich zur Bekanntheit des jungen Musikgenies bei."}]'::jsonb, ''),
  ('millionenzimma', 'Millionenzimma', '', '', '', '', 'Millionenzimmer', '[{"kategorie": "allg.", "text": "\"einer der prunkvollsten und luxuriösesten Räume des [[Schlosses]] Schönbrunn\""}, {"kategorie": "", "text": "Es befindet sich im Ostflügel des Schlosses Schönbrunn und ist Teil der Kaiserappartements. Es gehört zu den Privaträumen von [[Kaiserin]] Maria Theresia"}, {"kategorie": "", "text": "Die Wände des Millionenzimmers sind mit wertvollen, dunkelbraunen Palisanderholzvertäfelungen verkleidet, die aufwendig geschnitzt und vergoldet sind. Diese Holzarbeiten allein sind von außerordentlicher künstlerischer und handwerklicher Qualität"}, {"kategorie": "", "text": "Das herausragende Merkmal des Millionenzimmers sind die mehr als 200 wertvollen indischen und persischen Miniaturen aus dem 16. und 17. Jahrhundert, die in die Wandvertäfelungen eingefügt sind. Diese Miniaturen stammen aus der Mogulzeit und zeigen Szenen aus dem Hofleben, der Jagd und der Religion. Sie wurden im Rahmen der Rokoko-Innenraumgestaltung in Wien auf Goldgrund montiert, was ihnen einen besonderen Glanz verleiht"}, {"kategorie": "", "text": "Der Name \"Millionenzimmer\" leitet sich von der damals unglaublich hohen Summe ab, die für die Gestaltung dieses Raumes aufgewendet wurde. Das Zimmer galt schon zur Zeit seiner Entstehung als unermesslich wertvoll."}]'::jsonb, ''),
  ('gloriitte', 'Gloriitte', '', '', '', '', 'Gloriette', '[{"kategorie": "allg.", "text": "beeindruckender, klassizistischer Pavillon im [[Schloss]] Schönbrunn, der auf einem Hügel im Schlosspark steht und eine der bekanntesten Sehenswürdigkeiten des Schlosses darstellt"}, {"kategorie": "", "text": "Die Gloriette befindet sich auf der Anhöhe des Schönbrunner Bergs, direkt gegenüber dem Schloss Schönbrunn. Von hier aus hat man eine weitreichende Aussicht über die Gartenanlage und die Stadt Wien"}, {"kategorie": "", "text": "Die Gloriette wurde im Jahr 1775 nach den Plänen des Architekten Johann Ferdinand Hetzendorf von Hohenberg errichtet. Sie ist im klassizistischen Stil gestaltet und zeichnet sich durch eine symmetrische Fassade mit Rundbogenarkaden, korinthischen Säulen und einem markanten Mittelteil mit großen Fensteröffnungen aus"}, {"kategorie": "", "text": "Das Dach der Gloriette ist flach und begehbar, wodurch es als Aussichtsplattform dient. Eine zentrale Figurengruppe, die Kaiseradler und Trophäen darstellt, krönt die Mitte des Baus und betont die monumentale Wirkung der Struktur"}, {"kategorie": "", "text": "Die Gloriette ist ein herausragendes Beispiel für die klassizistische Architektur des 18. Jahrhunderts. Die harmonische Proportionierung und die Verwendung von Säulen und Bögen verleihen dem Bau eine elegante und majestätische Erscheinung. Die Skulpturen, die die Gloriette schmücken, sind Werke von Johann Baptist Hagenauer und stellen allegorische Figuren dar, die Macht, Ruhm und Sieg symbolisieren:  6. Der Name \"Gloriette\" stammt aus dem Französischen und leitet sich vom Wort \"gloire\" ab, was \"Ruhm\" oder \"Ehre\" bedeutet. Eine \"Gloriette\" bezeichnet in der Gartenarchitektur einen kleinen, oft pavillonartigen Bau, der als Zierde und als Aussichtspunkt dient. Der Begriff wurde besonders im 18. Jahrhundert in der Barockzeit verwendet, um solche Bauwerke zu bezeichnen, die als Höhepunkt oder krönender Abschluss einer Gartenanlage fungierten."}]'::jsonb, ''),
  ('neptunbrunnan', 'Neptunbrunnan', '', '', '', '', 'Neptunbrunnen', '[{"kategorie": "allg.", "text": "\"monumentaler Brunnen im Schlosspark [[Schönbrunn]] und eines der beeindruckendsten Wasserspiele der barocken Gartenanlage\""}, {"kategorie": "", "text": "Der Brunnen ist nach dem römischen Meeresgott Neptun benannt und spielt eine zentrale Rolle im Gartendesign von Schönbrunn, sowohl als künstlerisches Highlight als auch als Symbol für die Macht und Herrschaft der Habsburger"}, {"kategorie": "", "text": "Der Neptunbrunnen befindet sich am Ende der Hauptachse des Schlossparks, direkt am Fuße des Schönbrunner Bergs, unterhalb der [[Gloriette]]. Durch seine Platzierung bildet der Brunnen den optischen Abschluss der zentralen Gartenanlage"}, {"kategorie": "", "text": "Der Brunnen wurde zwischen 1776 und 1780 im Auftrag von Kaiserin Maria Theresia errichtet und ist ein herausragendes Beispiel für die barocke Gartenkunst und Architektur. Die Gestaltung übernahm der Architekt Johann Ferdinand Hetzendorf von Hohenberg, der auch für die [[Gloriette]] verantwortlich war"}, {"kategorie": "", "text": "Die zentrale Figurengruppe des Brunnens stellt den Gott Neptun dar, der auf einem Muschelwagen steht. Neptun wird von der Wassernymphe Thetis begleitet, die ihn um die sichere Rückkehr ihres Sohnes Achilles aus dem Trojanischen Krieg bittet"}, {"kategorie": "", "text": "Umgeben ist Neptun von Tritonen und Meereswesen, die aus den Wellen auftauchen. Die Skulpturen sind meisterhafte Arbeiten des Bildhauers Wilhelm Beyer und vermitteln Dynamik und Dramatik durch ihre kraftvollen Posen und detaillierten Ausführungen"}, {"kategorie": "", "text": "Der Neptunbrunnen symbolisiert die Herrschaft Neptuns über das Wasser, was in der barocken Symbolik oft als Allegorie auf die weltliche Macht verstanden wird. Für die Habsburger bedeutete dies die Manifestation ihrer Kontrolle und Souveränität über ihre Reiche."}]'::jsonb, ''),
  ('poimanhaus', 'Poimanhaus', '', '', '', '', 'Palmenhaus', '[{"kategorie": "allg.", "text": "\"beeindruckendes historisches Gewächshaus und eines der größten seiner Art in Europa\""}, {"kategorie": "", "text": "Es befindet sich im 13. Wiener Gemeindebezirk ([[Hietzing]]) und ist ein bedeutendes Beispiel für die Architektur des späten 19. Jahrhunderts sowie eine zentrale Attraktion des Schlossparks [[Schönbrunn]]"}, {"kategorie": "", "text": "Das Palmenhaus wurde zwischen 1880 und 1882 im Auftrag von [[Kaiser]] Franz Joseph I. erbaut. Es besteht aus einer beeindruckenden Eisen-Glas-Konstruktion im Stil des [[Historismus]]. Es ist 113 Meter lang, 28 Meter breit und erreicht in der Mitte eine Höhe von 25 Metern. Rund 45.000 Glasscheiben wurden für den imposanten Bau verarbeitet. Mit einer Grundfläche von 2.500 Quadratmetern und einer Glasfläche von 4.900 Quadratmetern zählt es zu den größten Palmenhäusern auf dem europäischen Kontinent"}, {"kategorie": "", "text": "Das Palmenhaus beherbergt eine umfangreiche Sammlung exotischer Pflanzen aus verschiedenen Klimazonen der Erde. Es ist in drei Bereiche unterteilt: einen tropischen Bereich im Mittelpavillon, einen temperierten Bereich im Ostpavillon und einen kühlen Bereich im Westpavillon"}, {"kategorie": "", "text": "Ein weiteres Plamenhaus befindet sich im Wiener [[Burggarten]]."}]'::jsonb, ''),
