  ('schraufndaumpfa', 'Schraufndaumpfa', '', '', '', 'Grundwortschatz Wienerisch', 'Schraubendampfer', '[{"kategorie": "wörtlich", "text": "\"Schraubendampfer\" (=\"mit Schiffsschrauben angetriebener Dampfer\" - Determinativkompositum aus \"Schraube\"=\" \"Schiffsschraube\" und \"Dampfer\"=\"Fregatte\")"}, {"kategorie": "hist., scherzhaft für", "text": "\"Schuhkufe\", \"Schraubkufe\" (antiquierte Eislaufkufe zum Anschrauben an den Schuh)"}, {"kategorie": "bezogen auf das weibliche Geschlecht", "text": "\"aufgetakelte Matrone\", \"Zimtzicke\", \"Schreckschraube\", \"Möchtegern-Diva\""}]'::jsonb, 'Waunn I eislaufn gee, bind I ma de oidn Schraufndaumpfa von mein Opa aunan Fuass - und zack, wiad aus mein Schdiifä a Eislaufschuach!'),
  ('schraufn', 'Schraufn', 'der', '', '', 'Grundwortschatz Wienerisch', 'Schraufen', '[{"kategorie": "wörtlich", "text": "\"Schraube\" (vom mittelhochdeutschen \"schrûbe\"=\"Schraube\")"}, {"kategorie": "techn.", "text": "\"Schraube\" (mit Gewinde und Kopf versehener Metallbolzen), Schiffsschraube, Bootsschraube"}, {"kategorie": "fig., bezogen auf das weibliche Geschlecht", "text": "\"Schreckschraube\", \"Zimtzicke\", \"Nervensäge\", \"Keifhexe\", \"Krawallschachtel\", [[Trulla]]"}, {"kategorie": "Fußballerjargon", "text": "hohe Niederlage, schmerzliche Niederlage, \"Packung\", \"Klatsche\" (früher war es unter Fußballfans üblich, Anhängern des gegnerischen Vereins vor oder nach dem Spiel eine überdimensionierte Schraube samt Mutter in die Hand zu drücken – als augenzwinkernde Kampfansage oder bitteres Andenken an eine ordentliche Klatsche)"}]'::jsonb, 'Pass auf, dassd in Schraufn ned iwadraasd, sunst reissds Gwind aus!'),
  ('schreifal', 'Schreifal', '', '', '', 'Grundwortschatz Wienerisch', 'Schräuferl', '[{"kategorie": "wörtlich", "text": "\"Schräubchen\" (Diminutiv von \"Schraube\" - vom mittelhochdeutschen \"schrûbe\"=\"Schraube\")"}, {"kategorie": "allg.", "text": "\"kleine Schraube\", \"kleines Schräubchen\""}, {"kategorie": "scherzhaft für", "text": "\"Ohrschräubchen\", Männerohrring, \"Ohrstecker\", \"Ohrclip\""}]'::jsonb, 'Pass auf beim Zsaummbaun - ned dass des Schreifal valuan geed!'),
  ('schreewagoatn', 'Schreewagoatn', '', '', '', '', 'Schrebergarten', '[{"kategorie": "", "text": "Wiener Kleingarten (Namensgeber: Dr. Moritz Schreber [1808-1861], Arzt in Leipzig, wo auch die ersten Schrebergärten entstanden)"}, {"kategorie": "", "text": "Kleingartenparzelle (abgemessenes Stück Land, das sich in einer Kleingartenanlage [\"Kolonie\"] befindet. Diese wiederum besteht aus mehreren Einzelgärten. Ein Kleingarten kann dabei maximal 400 qm messen)"}]'::jsonb, ''),
  ('schrecknbeaga', 'Schrecknbeaga', '', '', '', '', 'Schreckenberger', '[{"kategorie": "ursprünglich", "text": "sächsische Silbermünze (nach den Silberminen des \"Schreckenberges\" in Sachsen [heute \"Annaberg\"] scherzhaft auch \"Schreckenberger genannt)"}, {"kategorie": "scherzhaft für", "text": "beängstigende Nachricht, furchterregende Mitteilung, düstere Botschaft, Drohung"}]'::jsonb, ''),
  ('schreckschraufn', 'Schreckschraufn', '', '', '', 'Grundwortschatz Wienerisch', 'Schreckschraufen', '[{"kategorie": "wörtlich", "text": "\"Schreckschraube\" (Determinativkompositum aus \"Schreck\"=\"Schrecken\" und \"Schraube\"=\"geschraubte Matrone\")"}, {"kategorie": "bezogen auf das weibliche Geschlecht", "text": "\"unerträgliches Frauenzimmer\" , \"Zimtzicke\", \"Nervensäge\", \"Keifhexe\", \"Krawallschachtel\", [[Tussi]], [[Trulla]], [[Grammel]], [[Bissgurn]], [[Beisszangl]]"}]'::jsonb, 'Waunnsd in da Fria neem dera Schreckschraufn aufwochsd, brauchsd kaan Kaffee mea - do bist schoo munta vua lauta Aungst!'),
