  ('noschmoakd', 'Noschmoakd', '', '', '', '', 'Naschmarkt', '[{"kategorie": "ursprünglich, wörtlich", "text": "\"Aschenmarkt\" (benannt nach dem einstigen Aschenplatz vor dem Freihaus, ab dem 19. Jahrundert verballhornt zu \"Naschmarkt\"; eine andere Legende besagt, dass sich der Name \"Naschmarkt\" von den hier ursprünglich verkauften \"Asch\" (Milchprodukten) ableiten soll, auch wenn diese Theorie nicht eindeutig belegt ist)"}, {"kategorie": "", "text": "Wiener Naschmarkt (Wiens beliebtester Markt, er liegt an der Wienzeile über dem überdachten [[Wienfluss]], ist ca. 1,5 Kilometer lang und erstreckt sich entlang der Linken Wienzeile vom [[Getreidemarkt]] im Osten bis zur [[Kettenbrückengasse]] im Westen"}, {"kategorie": "", "text": "Der Naschmarkt ist nicht nur ein Ort des Handels, sondern auch ein kulturelles und soziales Zentrum in Wien. Er verbindet die Tradition des Markthandels mit der Vielfalt moderner urbaner Lebensweisen und bleibt ein unverzichtbarer Teil des Wiener Stadtlebens."}]'::jsonb, ''),
  ('kettnbrueckngossn', 'Kettnbrückngossn', '', '', '', '', 'Kettenbrückengasse', '[{"kategorie": "allg.", "text": "Straße im 4. Wiener Gemeindebezirk ([[Wieden]]), die sich von der Margaretenstraße im Süden bis zur [[Rechten]] Wienzeile im Norden erstreckt und in unmittelbarer Nähe zum Naschmarkt liegt"}, {"kategorie": "", "text": "Der Name \"Kettenbrückengasse\" leitet sich von der historischen Kettenbrücke ab, die einst über den Wienfluss führte. Diese Brücke wurde im 19. Jahrhundert errichtet, um die damals aufstrebenden Stadtteile miteinander zu verbinden, und trug zu einer verbesserten Verkehrsverbindung in Wien bei. Die Brücke existiert heute nicht mehr, aber die Straße und die U-Bahn-Station tragen weiterhin den Namen als Erinnerung an dieses historische Bauwerk."}]'::jsonb, ''),
  ('schdaandlarin', 'Schdaandlarin', '', '', '', '', 'Standlerin', '[{"kategorie": "wörtlich", "text": "\"Marktstandlerin\" (vom mittelhochdeutschen \"stant\"=\"Stand\")"}, {"kategorie": "", "text": "Betreiberin eines Marktstandes in der Innenstadt (im Gegensatz zur [[Höckerin]], die diesen in der Vorstadt betreibt)"}]'::jsonb, ''),
  ('schdaandla', 'Schdaandla', '', '', '', '', 'Standler', '[{"kategorie": "wörtlich", "text": "\"Marktstandler\" (vom mittelhochdeutschen \"stant\"=\"Stand\")"}, {"kategorie": "", "text": "Marktstandverkäufer, Betreiber eines Marktstandes"}]'::jsonb, ''),
  ('hoeckarin', 'Höckarin', '', '', '', '', 'Höckerin', '[{"kategorie": "wörtlich", "text": "Betreiberin eines Marktstandes in der Vorstadt (im Gegensatz zur [[Standlerin]], die diesen in der Innenstadt betreibt)"}]'::jsonb, ''),
  ('mameatus', 'Mameatus', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Mamertus', '[{"kategorie": "wörtlich", "text": "\"Mamertus\" (vom lateinischen \"mamertus\"=\"dem Mars geweiht\")"}, {"kategorie": "rel.", "text": "\"Mamertus, Erzbischof von Vienne\" (christlicher Heiliger, Südgallien, Frankreich, 5. Jahrhundert), \"der erste der fünf [[Eisheiligen]]\" (Gedenktag nach dem volkstümlichen Bauernkalender: 11. Mai), \"Schutzheiliger gegen Unwetter, Erdbeben und Missernte\""}]'::jsonb, ''),
  ('pankratius', 'Pankratius', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Pankratius', '[{"kategorie": "wörtlich", "text": "\"Pankratius\" (vom griechischen \"pankratos\"=\"der ganz Starke\")"}, {"kategorie": "rel.", "text": "\"Pankratius von Rom\" (christlicher Märtyrer und Heiliger, ca. 290 – † um 304 n. Chr., der als Jugendlicher während der Christenverfolgungen unter Kaiser Diokletian wegen seines Glaubens enthauptet wurde – etwa im Alter von 14 Jahren. Bereits im 4. Jahrhundert wurde er als Märtyrer verehrt; sein Grab befindet sich in der Basilika San Pancrazio in Rom), \"der zweite der fünf [[Eisheiligen]]\" (Gedenktag nach dem volkstümlichen Bauernkalender: 12. Mai), \"Schutzheiliger gegen Unwetter, Erdbeben und Missernte\""}]'::jsonb, ''),
  ('bonifatius', 'Bonifatius', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Bonifatius', '[{"kategorie": "wörtlich", "text": "\"Bonifatius\" (vom lateinischen \"bonum facere\"=\"jemand, der Gutes tut\")"}, {"kategorie": "rel.", "text": "\"Bonifatius von Tarsus\" († um 306 n. Chr., christlicher Märtyrer und Heiliger, der während der Christenverfolgungen unter Kaiser Diokletian den Märtyrertod starb. Der Legende nach war er ursprünglich Diener und Lebensgefährte der adligen Römerin Aglaë. Er reiste in ihrem Auftrag ins Morgenland, um Reliquien von Märtyrern zu finden – und wurde selbst als Bekenner des Glaubens hingerichtet.Südgallien, Frankreich, 5. Jahrhundert), \"der vierte der fünf [[Eisheiligen]]\" (Gedenktag nach dem volkstümlichen Bauernkalender: 14. Mai), \"Schutzheiliger gegen Unwetter, Erdbeben und Missernte\""}]'::jsonb, ''),
  ('servatius', 'Servatius', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Servatius', '[{"kategorie": "wörtlich", "text": "\"Servatius\" (vom lateinischen \"servatius\"=\"der Errettete\")"}, {"kategorie": "rel.", "text": "\"Servatius von Tongern († um 384 n. Chr., christlicher Heiliger, Bischof von Tongern [heutiges Belgien], gilt als einer der frühesten bekannten Bischöfe nördlich der Alpen. Der Legende nach war er Verteidiger des Glaubens gegen arianische Irrlehren und wurde als Wundertäter verehrt. Er wird besonders mit Maastricht verbunden, wo sich auch seine Grabstätte und die Servatius-Basilika befinden), \"der dritte der fünf [[Eisheiligen]]\" (Gedenktag nach dem volkstümlichen Bauernkalender: 13. Mai), \"Schutzheiliger gegen Unwetter, Erdbeben und Missernte\""}]'::jsonb, 'Servaz muss vorüber sein, willst vor Nachtfrost sicher sein!'),
  ('soffal', 'Soffal', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Sopherl', '[{"kategorie": "wörtlich", "text": "\"Sophie\" (vom griechischen \"sofia\"=\"die Weise\")"}, {"kategorie": "rel.", "text": "\"Sophia von Rom\" (frühchristliche Märtyrin des 4. Jahrhunderts, die um 304 während der Diokletianischen Christenverfolgung starb, wird auch als Mutter der Heiligen Pistis [Glaube], Elpis [Hoffnung] und Agape [Liebe] dargestellt. In der Spätantike und im Mittelalter wurde sie als Symbol der Weisheit und standhaften Frömmigkeit verehrt. Ihre Grabstätte soll sich an der Via Aurelia in Rom befinden), \"die fünfte und letzte der fünf [[Eisheiligen]]\" (Gedenktag nach dem volkstümlichen Bauernkalender: 15. Mai), \"Schutzheilige gegen Unwetter, Erdbeben und Missernte\" (Patronin für das Gedeihen der Feldfrüchte, nach deren Namenstag am 15. Mai es keinen Spätfrost mehr geben sollte)"}]'::jsonb, ''),
  ('sutteraeu', 'Sutteräu', '', '', '', '', 'Souterrain', '[{"kategorie": "wörtlich", "text": "\"teilweise oder ganz unter der Erde liegendes Geschoß eines Hauses\" (vom französischen \"souterrain\"=\"unterirdisch\")"}, {"kategorie": "allg.", "text": "Tiefparterre, \"Halbkeller\""}]'::jsonb, ''),
  ('schbochtln', 'schbochtln', '', '', '', '', 'spachteln', '[{"kategorie": "wörtlich", "text": "\"durch Auftragen von Spachtelmasse gätten\" (vom mittelhochdeutschen \"spatel\"=\"flaches, schmales Schäufelchen\")"}, {"kategorie": "scherzhaft für", "text": "schlemmen, schmausen, [[schnabulieren]], [[sich]] anbampfen, [[schlampampen]]"}]'::jsonb, ''),
  ('luzifeal', 'Luzifeal', '', '', '', '', 'Luziferl', '[{"kategorie": "wörtlich", "text": "\"Teufelchen\" (vom lateinischen \"lucifer\"=\"Teufel\" [wörtlich: \"Lichtträger\"])"}, {"kategorie": "allg.", "text": "Teufel, Satan, Dämon"}, {"kategorie": "scherzhaft für", "text": "lebhaftes Kind, \"kleiner Sausewind\", [[Ramsamperl]], [[Bakschieserl]], [[Springinkerl]], [[Spirifankerl]] (Zur Erklärung: Bekannt ist die Wiener Sage von den drei Teufelchen [[Luziferl]], [[Spirifankerl]] und [[Springinkerl]]\", die als in Stein gebannte Figuren an der Kirchenmauer des Stephansdoms zu sehen sind)"}]'::jsonb, ''),
  ('fankal', 'Fankal', '', '', '', '', 'Fankerl', '[{"kategorie": "wörtlich", "text": "\"Teufelchen\" (vom mittelhochdeutschen \"vanke\"=\"Funke\", synonym für \"vâlant\"=\"Teufel\")"}, {"kategorie": "allg.", "text": "Teufel, Satan, Dämon, Tod"}, {"kategorie": "scherzhaft für", "text": "lebhaftes Kind, \"kleiner Sausewind\", [[Ramsamperl]], [[Bakschieserl]], [[Springinkerl]], [[Spirifankerl]] (Zur Erklärung: Bekannt ist die Wiener Sage von den drei Teufelchen [[Luziferl]], [[Spirifankerl]] und [[Springinkerl]]\", die als in Stein gebannte Figuren an der Kirchenmauer des Stephansdoms zu sehen sind)"}]'::jsonb, ''),
